{"file_path":"src/parser.js","content":"/**
 * Parsing of the build-graph description read from standard input.
 */

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

export class ParseError extends Error {}
export class UnknownTaskError extends Error {
  constructor(name) {
    super(`unknown task ${name}`)
    this.name = 'UnknownTaskError'
  }
}

/**
 * Parses the input text into a graph: a map of task name -> cost, and a map
 * of task name -> Set of dependency names.
 */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const deps = new Map()
  const depUsages = []

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new ParseError(`line ${lineNum}: expected task <name> <cost>`)
      }
      const name = words[1]
      const costStr = words[2]
      if (!NAME_RE.test(name)) {
        throw new ParseError(`line ${lineNum}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new ParseError(`line ${lineNum}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new ParseError(`line ${lineNum}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(costStr, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new ParseError(`line ${lineNum}: expected dep <name> <dependency>...`)
      }
      const name = words[1]
      if (!NAME_RE.test(name)) {
        throw new ParseError(`line ${lineNum}: invalid task name ${name}`)
      }
      depUsages.push(name)
      let set = deps.get(name)
      if (!set) {
        set = new Set()
        deps.set(name, set)
      }
      for (const dn of words.slice(2)) {
        if (!NAME_RE.test(dn)) {
          throw new ParseError(`line ${lineNum}: invalid task name ${dn}`)
        }
        depUsages.push(dn)
        set.add(dn)
      }
    } else {
      throw new ParseError(`line ${lineNum}: unknown directive ${directive}`)
    }
  }

  for (const name of tasks.keys()) {
    if (!deps.has(name)) deps.set(name, new Set())
  }

  for (const n of depUsages) {
    if (!tasks.has(n)) throw new UnknownTaskError(n)
  }

  return { tasks, deps }
}
"}

