{"file_path":"src/graph.js","content":"/**
 * Graph analysis: cycle detection, wave/timing computation, and priority
 * (longest downstream chain) computation, used by the waves/explain/pack
 * commands.
 */

/**
 * Finds the first cycle a depth-first search discovers, starting from each
 * task in ascending name order and walking dependencies in ascending order.
 * Returns an array of names from the re-entered task, through the stack,
 * back to that task, or null when the graph is acyclic.
 */
export function findCycle(tasks, deps) {
  const state = new Map()
  const stack = []

  function dfs(name) {
    state.set(name, 1)
    stack.push(name)
    const ds = [...deps.get(name)].sort()
    for (const d of ds) {
      const st = state.get(d) || 0
      if (st === 1) {
        const idx = stack.indexOf(d)
        const cyc = stack.slice(idx)
        cyc.push(d)
        return cyc
      } else if (st === 0) {
        const res = dfs(d)
        if (res) return res
      }
    }
    stack.pop()
    state.set(name, 2)
    return null
  }

  const names = [...tasks.keys()].sort()
  for (const n of names) {
    if (!state.get(n)) {
      const res = dfs(n)
      if (res) return res
    }
  }
  return null
}

/**
 * Computes, for every task, its start time, finish time and wave depth,
 * assuming unlimited workers. Deps must already be known acyclic.
 */
export function computeTimings(tasks, deps) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()
  const memo = new Set()

  function compute(name) {
    if (memo.has(name)) return
    memo.add(name)
    const ds = deps.get(name)
    let s = 0
    let dep = 0
    for (const d of ds) {
      compute(d)
      if (finish.get(d) > s) s = finish.get(d)
      if (depth.get(d) + 1 > dep) dep = depth.get(d) + 1
    }
    start.set(name, s)
    finish.set(name, s + tasks.get(name))
    depth.set(name, dep)
  }

  for (const name of tasks.keys()) compute(name)

  return { start, finish, depth }
}

/**
 * Computes, for every task, the cost of the longest chain that begins at
 * it: its own cost plus the costs down to any task that nothing depends on.
 */
export function computePriority(tasks, deps) {
  const children = new Map()
  for (const name of tasks.keys()) children.set(name, [])
  for (const [name, ds] of deps) {
    for (const d of ds) children.get(d).push(name)
  }

  const priority = new Map()

  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const c of children.get(name)) {
      const p = compute(c)
      if (p > best) best = p
    }
    const val = tasks.get(name) + best
    priority.set(name, val)
    return val
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}

/**
 * Simulates the build on the given number of workers, following the greedy
 * priority-based scheduling rule described in the specification.
 */
export function packWorkers(tasks, deps, workerCount) {
  const priority = computePriority(tasks, deps)
  const names = [...tasks.keys()]
  const finishTime = new Map()
  const started = new Set()
  const workers = []
  for (let i = 0; i < workerCount; i++) workers.push({ freeAt: 0, log: [] })

  const remaining = new Set(names)

  let time = 0
  while (remaining.size > 0) {
    // Try to start as many tasks as possible at the current instant.
    for (;;) {
      const freeWorkers = []
      for (let i = 0; i < workers.length; i++) {
        if (workers[i].freeAt <= time) freeWorkers.push(i)
      }
      if (freeWorkers.length === 0) break

      const ready = []
      for (const name of remaining) {
        const ds = deps.get(name)
        let ok = true
        for (const d of ds) {
          if (!(finishTime.has(d) && finishTime.get(d) <= time)) {
            ok = false
            break
          }
        }
        if (ok) ready.push(name)
      }
      if (ready.length === 0) break

      ready.sort((a, b) => {
        const pa = priority.get(a)
        const pb = priority.get(b)
        if (pa !== pb) return pb - pa
        return a < b ? -1 : a > b ? 1 : 0
      })

      const chosen = ready[0]
      const workerIdx = freeWorkers[0]
      const cost = tasks.get(chosen)
      const finish = time + cost
      workers[workerIdx].freeAt = finish
      workers[workerIdx].log.push({ name: chosen, start: time, finish })
      finishTime.set(chosen, finish)
      started.add(chosen)
      remaining.delete(chosen)
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (const w of workers) {
      if (w.freeAt > time && w.freeAt < next) next = w.freeAt
    }
    time = next
  }

  return workers
}
"}

