    let s = 0
    let dep = 0
    for (const d of ds) {
      compute(d)
      if (finish.get(d) > s) s = finish.get(d)
      if (depth.get(d) + 1 > dep) dep = depth.get(d) + 1
    }
    start.set(name, s)
    finish.set(name, s + tasks.get(name))
