  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const c of children.get(name)) {
      const p = compute(c)
      if (p > best) best = p
    }
    const val = tasks.get(name) + best
    priority.set(name, val)
    return val
  }

  for (const name of tasks.keys()) compute(name)
