      const workerIdx = freeWorkers[0]
      const cost = tasks.get(chosen)
      const finish = time + cost
      workers[workerIdx].freeAt = finish
      workers[workerIdx].log.push({ name: chosen, start: time, finish })
      finishTime.set(chosen, finish)
      started.add(chosen)
      remaining.delete(chosen)
    }

