/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { parseGraph, ParseError, UnknownTaskError } from './parser.js'
import { findCycle, computeTimings, packWorkers } from './graph.js'

function usageError() {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
  process.exit(2)
}

function readStdin() {
  const fs = require === undefined ? null : null
  return ''
}

async function readStdinAsync() {
  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  return Buffer.concat(chunks.map((c) => (typeof c === 'string' ? Buffer.from(c) : c))).toString('utf8')
}

async function main() {
  const argv = process.argv.slice(2)

  let mode
  let workers = null

  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    mode = argv[0]
  } else if (argv.length === 2 && argv[0] === 'pack') {
    mode = 'pack'
    const w = argv[1]
    if (!/^[1-9][0-9]*$/.test(w)) {
      process.stderr.write('error: workers must be a positive integer\n')
      process.exit(2)
    }
    workers = parseInt(w, 10)
  } else {
    usageError()
    return
  }

  const input = await readStdinAsync()

  let graph
  try {
    graph = parseGraph(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
      return
    }
    if (err instanceof UnknownTaskError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
      return
    }
    throw err
  }

  const { tasks, deps } = graph

  const cycle = findCycle(tasks, deps)
  if (cycle) {
    process.stderr.write(`error: cycle: ${cycle.join(' -> ')}\n`)
    process.exit(3)
    return
  }

  if (mode === 'waves' || mode === 'explain') {
    const { start, finish, depth } = computeTimings(tasks, deps)
    const names = [...tasks.keys()].sort()
    let total = 0
    for (const n of names) if (finish.get(n) > total) total = finish.get(n)

    if (mode === 'waves') {
      let maxDepth = -1
      for (const n of names) if (depth.get(n) > maxDepth) maxDepth = depth.get(n)
      const waves = []
      for (let k = 0; k <= maxDepth; k++) waves.push([])
      for (const n of names) waves[depth.get(n)].push(n)
      let out = ''
      for (let k = 0; k <= maxDepth; k++) {
        out += `wave ${k}: ${waves[k].sort().join(' ')}\n`
      }
      out += `total ${total}\n`
      process.stdout.write(out)
    } else {
      let out = ''
      for (const n of names) {
        out += `${n} start=${start.get(n)} finish=${finish.get(n)} depth=${depth.get(n)}\n`
      }
      out += `total ${total}\n`
      process.stdout.write(out)
    }
  } else {
    const workerLogs = packWorkers(tasks, deps, workers)
    let makespan = 0
    for (const w of workerLogs) {
      for (const t of w.log) if (t.finish > makespan) makespan = t.finish
    }
    let out = ''
    for (let i = 0; i < workerLogs.length; i++) {
      const w = workerLogs[i]
      const parts = w.log.map((t) => ` ${t.name}@${t.start}-${t.finish}`).join('')
      out += `worker ${i}:${parts}\n`
    }
    out += `makespan ${makespan}\n`
    process.stdout.write(out)
  }
}

main().catch((err) => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exit(2)
})
"}

